<template><div class="page"><div class="page-head"><div><h2>核销记录</h2><p>核销和冲正均保留原记录，方便追溯服务人员与确认收入。</p></div></div><div class="toolbar"><el-input v-model="query.keyword" clearable placeholder="核销号 / 卡号 / 姓名 / 手机号 / 操作人" @keyup.enter="reload"/><el-select v-model="query.status" clearable placeholder="全部状态"><el-option label="核销成功" value="success"/><el-option label="已冲正" value="reversed"/></el-select><el-button type="primary" @click="reload">查询</el-button><el-button @click="reset">重置</el-button></div><el-table :data="rows" v-loading="loading"><el-table-column label="服务与客户" min-width="240"><template #default="{row}"><b>{{ row.item_name }}</b><div class="sub">{{ row.holder_name }} · {{ mask(row.holder_mobile) }}</div></template></el-table-column><el-table-column label="核销记录" min-width="220"><template #default="{row}">{{ row.redeem_no }}<div class="sub">{{ time(row.occurred_at) }}</div></template></el-table-column><el-table-column label="次数" width="130"><template #default="{row}">{{ row.before_remaining }} → {{ row.after_remaining }}</template></el-table-column><el-table-column label="确认收入" width="130"><template #default="{row}">¥{{ money(row.recognized_amount) }}</template></el-table-column><el-table-column prop="operator_name" label="核销人" width="120"/><el-table-column label="状态" width="100"><template #default="{row}"><MemberCardStatusTag :value="row.status"/></template></el-table-column><el-table-column label="操作" width="110" align="right"><template #default="{row}"><el-button v-if="row.status==='success'" link type="warning" @click="reverse(row)">冲正</el-button><span v-else class="sub">{{ row.reverse_name||'—' }}</span></template></el-table-column></el-table><div class="pagination"><el-pagination v-model:current-page="query.page" v-model:page-size="query.limit" layout="total,prev,pager,next" :total="total" @current-change="load"/></div></div></template>
<script setup lang="ts">import{onMounted,reactive,ref}from'vue';import{ElMessage,ElMessageBox}from'element-plus';import{getCardRedemptions,memberCardRequestId,reverseCardRedemption}from'../../api';import MemberCardStatusTag from'../../components/MemberCardStatusTag.vue';const query=reactive({keyword:'',status:'',page:1,limit:15}),rows=ref<any[]>([]),total=ref(0),loading=ref(false);const money=(v:any)=>Number(v||0).toFixed(2),time=(v:any)=>v?new Date(Number(v)*1000).toLocaleString('zh-CN',{hour12:false}):'—',mask=(v:string)=>/^\d{11}$/.test(v||'')?`${v.slice(0,3)}****${v.slice(-4)}`:(v||'—');const load=async()=>{loading.value=true;try{const d:any=(await getCardRedemptions(query)).data||{};rows.value=d.data||[];total.value=d.total||0}finally{loading.value=false}};const reload=()=>{query.page=1;load()};const reset=()=>{query.keyword='';query.status='';reload()};const reverse=async(row:any)=>{const{value}=await ElMessageBox.prompt('冲正会恢复本次扣减的次数，请填写真实原因。','核销冲正',{inputValidator:v=>!!String(v||'').trim()||'必须填写原因',type:'warning'});await reverseCardRedemption(row.id,{request_id:memberCardRequestId('reverse'),reason:value});ElMessage.success('核销已冲正，次数已恢复');load()};onMounted(load)</script>
<style scoped>.page{min-height:100%;padding:20px;box-sizing:border-box;background:var(--el-bg-color)}.page-head{margin-bottom:20px}.page-head h2{margin:0;font-size:20px;font-weight:500}.page-head p{margin:6px 0 0;color:var(--el-text-color-secondary)}.toolbar{display:flex;gap:10px;margin-bottom:14px;padding:14px 16px;border-radius:4px;background:var(--el-fill-color-lighter)}.toolbar .el-input{width:360px}.toolbar .el-select{width:150px}.sub{margin-top:5px;color:var(--el-text-color-secondary);font-size:12px}.pagination{display:flex;justify-content:flex-end;margin-top:16px}</style>
